// ═══════════════════════════════════════════════════════════════════════
// Build per-workspace Notion query payload
// ═══════════════════════════════════════════════════════════════════════
// Input: N rows (one per workspace) with workspace + last_synced timestamp
// Output: N items, each carrying token + ds_id + URL + body for HTTP node
// ═══════════════════════════════════════════════════════════════════════

const WORKSPACES = {
  vt_intelligence: {
    token: $env.NOTION_TOKEN_VT_INTELLIGENCE,
    brand_ds_id: $env.NOTION_DB_BRANDS_VT_INTELLIGENCE,
  },
  the_gifted_synapse: {
    token: $env.NOTION_TOKEN_THE_GIFTED_SYNAPSE,
    brand_ds_id: $env.NOTION_DB_BRANDS_THE_GIFTED_SYNAPSE,
  },
};

const out = [];
for (const item of $input.all()) {
  const row = item.json;
  const ws = row.workspace;
  const config = WORKSPACES[ws];
  if (!config) continue;

  const lastSynced = row.last_synced || (new Date(Date.now() - 7 * 86400 * 1000).toISOString());
  const dsId = (config.brand_ds_id || '').replace('collection://', '');

  out.push({
    json: {
      _workspace: ws,
      _last_synced: lastSynced,
      _brand_count: row.brand_count,
      notion_token: config.token,
      notion_ds_id: dsId,
      query_url: `https://api.notion.com/v1/data_sources/${dsId}/query`,
      query_body: {
        filter: {
          timestamp: 'last_edited_time',
          last_edited_time: { after: lastSynced },
        },
        page_size: 100,
      },
    },
  });
}
return out;

// ═══════════════════════════════════════════════════════════════════════
// Parse Notion query responses → flatten + build full UPDATE SQL per page
// ═══════════════════════════════════════════════════════════════════════
// n8n's queryReplacement quietly drops empty params, breaking positional
// $1..$N matching. Solution: build the full UPDATE statement as a single
// SQL string here (with SQL-quoted values), then Postgres just executes it.
// ═══════════════════════════════════════════════════════════════════════

const PROP_MAP = {
  vt_intelligence: {
    brand_name:       'Brand Name',
    status:           'Status',
    brand_structure:  'Brand Structure',
    positioning_mode: 'Positioning Mode',
    brand_description: 'Brand Description',
    company:          'Company',
    brand_web_url:    'Website',
    gsc_property_url: 'GSC Property',
    ga4_property_id:  'GA4 Property ID',
  },
  the_gifted_synapse: {
    brand_name:       'Brand Name',
    status:           'Status',
    brand_structure:  'Brand Structure',
    positioning_mode: 'Positioning Mode',
    brand_description: 'Brand Description',
    company:          'Company',
    brand_web_url:    'Brand Web URL',
    gsc_property_url: 'GSC Property URL',
    ga4_property_id:  'GA4 Property ID',
  },
};

const STATUS_NOTION_TO_PG = {
  'ACTIVE': 'active',
  'IN ACTIVE': 'inactive',
  'PENDING': 'pending',
};

function s(v) { return v == null ? '' : String(v); }
function extractTitle(prop)  { if (!prop || !prop.title || !prop.title.length) return ''; return s(prop.title[0].plain_text); }
function extractText(prop)   { if (!prop || !prop.rich_text || !prop.rich_text.length) return ''; return s(prop.rich_text.map(t => t.plain_text).join('')); }
function extractSelect(prop) { if (!prop || !prop.select) return ''; return s(prop.select.name); }
function extractUrl(prop)    { if (!prop || !prop.url) return ''; return s(prop.url); }

// SQL-quote: 'value' or NULL if empty
function sql(v) {
  if (v == null || v === '') return 'NULL';
  return "'" + String(v).replace(/'/g, "''") + "'";
}

const out = [];
const inputs = $input.all();
const UPSTREAM = 'Code: build per-workspace Notion query';

for (let i = 0; i < inputs.length; i++) {
  const item = inputs[i];
  const resp = item.json;
  const status = resp.statusCode;
  const body = resp.body || {};

  let workspace = '';
  try {
    const up = $(UPSTREAM).itemMatching(i);
    workspace = up ? up.json._workspace : '';
  } catch (e) {
    const arr = $items(UPSTREAM);
    workspace = arr[i] ? arr[i].json._workspace : '';
  }

  if (status < 200 || status >= 300) {
    console.log('[N→S] Notion query failed for ' + workspace + ': status=' + status);
    continue;
  }

  const pages = body.results || [];
  const mapping = PROP_MAP[workspace];
  if (!mapping) continue;

  for (const page of pages) {
    const props = page.properties || {};
    const status_notion = extractSelect(props[mapping.status]);
    const status_pg = status_notion ? (STATUS_NOTION_TO_PG[status_notion] || '') : '';

    const vals = {
      brand_name:         extractTitle(props[mapping.brand_name]),
      brand_description:  extractText(props[mapping.brand_description]),
      company:            extractText(props[mapping.company]),
      brand_web_url:      extractUrl(props[mapping.brand_web_url]),
      gsc_property_url:   extractUrl(props[mapping.gsc_property_url]),
      ga4_property_id:    extractText(props[mapping.ga4_property_id]),
      brand_structure:    extractSelect(props[mapping.brand_structure]),
      positioning_mode:   extractSelect(props[mapping.positioning_mode]),
      status:             status_pg,
    };

    // Build full UPDATE — each field uses COALESCE so empty strings (→ SQL NULL) preserve existing
    const updateSql = `UPDATE brands SET
  brand_name         = COALESCE(${sql(vals.brand_name)}, brand_name),
  brand_description  = COALESCE(${sql(vals.brand_description)}, brand_description),
  company            = COALESCE(${sql(vals.company)}, company),
  brand_web_url      = COALESCE(${sql(vals.brand_web_url)}, brand_web_url),
  gsc_property_url   = COALESCE(${sql(vals.gsc_property_url)}, gsc_property_url),
  ga4_property_id    = COALESCE(${sql(vals.ga4_property_id)}, ga4_property_id),
  brand_structure    = COALESCE(${sql(vals.brand_structure)}, brand_structure),
  positioning_mode   = COALESCE(${sql(vals.positioning_mode)}, positioning_mode),
  status             = COALESCE(${sql(vals.status)}, status),
  notion_synced_at   = NOW(),
  updated_at         = NOW()
WHERE notion_id = ${sql(page.id)}
RETURNING brand_slug, brand_name, status, positioning_mode, notion_synced_at::time AS synced_at;`;

    out.push({
      json: {
        _notion_id: s(page.id),
        _workspace: s(workspace),
        _last_edited_time: s(page.last_edited_time),
        ...vals,
        update_sql: updateSql,
      },
    });
  }
}

if (out.length > 0) {
  console.log('[N→S] ' + out.length + ' UPDATE statements ready');
}
return out;
